<template>
  <div class="page-container implement-page">
    <div class="page-head"><div><h2>计划落实 · 按图选地</h2><p>基于地块清单和可视化网格选择落实地块，批量登记作物与落实状态。</p></div><el-tag type="primary">{{ userStore.role?.roleName || '当前角色' }} · {{ userStore.regionName }}</el-tag></div>
    <div class="stat-grid"><StatCard label="辖区地块" :value="plots.length" unit="块" icon="MapLocation" /><StatCard label="已落实" :value="implementedCount" unit="块" icon="CircleCheck" color="#2e9e5b" /><StatCard label="待落实" :value="pendingCount" unit="块" icon="Clock" color="#e6a23c" /><StatCard label="落实面积" :value="implementedArea.toLocaleString()" unit="亩" icon="DataLine" color="#409eff" /></div>
    <div class="content-grid">
      <div class="panel list-panel"><div class="panel-title"><span class="title-text">地块列表</span><div class="title-extra"><el-button size="small" @click="load">刷新</el-button><el-button size="small" type="primary" :disabled="!pendingSelected.length" @click="implement">批量落实（{{ pendingSelected.length }}）</el-button><el-button size="small" type="warning" :disabled="!implementedSelected.length" @click="cancelImplement">反向标注（{{ implementedSelected.length }}）</el-button><el-button size="small" @click="selectByCrop">按作物圈选</el-button><el-button size="small" type="success" @click="validateArea">面积校验</el-button></div></div>
        <el-form :inline="true" class="filters"><el-form-item label="作物"><el-select v-model="filters.crop" clearable placeholder="全部" style="width:120px"><el-option v-for="crop in crops" :key="crop.code" :label="crop.name" :value="crop.code" /></el-select></el-form-item><el-form-item label="状态"><el-select v-model="filters.status" clearable placeholder="全部" style="width:120px"><el-option label="待落实" value="pending" /><el-option label="已落实" value="implemented" /></el-select></el-form-item><el-form-item label="关键字"><el-input v-model="filters.keyword" clearable placeholder="地块/主体" style="width:180px" /></el-form-item></el-form>
        <el-table ref="tableRef" :data="filteredPlots" stripe height="calc(100vh - 360px)" @selection-change="selected = $event"><el-table-column type="selection" width="48" /><el-table-column prop="id" label="地块编号" width="90" /><el-table-column prop="name" label="地块名称" min-width="150" show-overflow-tooltip /><el-table-column prop="subjectName" label="经营主体" min-width="160" show-overflow-tooltip /><el-table-column prop="cropName" label="当前作物" width="85" /><el-table-column prop="area" label="面积(亩)" width="95" align="right" /><el-table-column label="状态" width="85"><template #default="{ row }"><el-tag size="small" :type="row.status === 'implemented' ? 'success' : 'warning'">{{ row.status === 'implemented' ? '已落实' : '待落实' }}</el-tag></template></el-table-column><el-table-column label="操作" width="70"><template #default="{ row }"><el-button link type="primary" @click="showDetail(row)">详情</el-button></template></el-table-column></el-table>
      </div>
      <div class="panel map-panel"><div class="panel-title"><span class="title-text">地块网格示意</span><span class="title-extra">点击地块查看详情</span></div><div class="plot-grid"><button v-for="plot in filteredPlots" :key="plot.id" class="plot-cell" :class="[plot.status, { selected: selected.some(item => item.id === plot.id) }]" @click="showDetail(plot)"><span>{{ plot.id.replace('PL-', '') }}</span><small>{{ plot.area }}亩</small></button></div><div class="legend"><span><i class="pending" />待落实</span><span><i class="implemented" />已落实</span><span><i class="selected" />已选择</span></div><div v-if="current" class="detail-card"><b>{{ current.name }}</b><p>{{ current.subjectName }} · {{ current.cropName }} · {{ current.area }}亩</p><el-tag size="small" :type="current.status === 'implemented' ? 'success' : 'warning'">{{ current.status === 'implemented' ? '已落实' : '待落实' }}</el-tag></div></div>
    </div>
    <el-dialog v-model="dialogVisible" title="批量落实地块" width="420px"><el-form label-width="85px"><el-form-item label="落实作物"><el-select v-model="crop" style="width:100%"><el-option v-for="item in crops" :key="item.code" :label="item.name" :value="item.code" /></el-select></el-form-item><el-form-item label="选择地块"><span>已选择 {{ selected.length }} 块，共 {{ selectedArea.toLocaleString() }} 亩</span></el-form-item></el-form><template #footer><el-button @click="dialogVisible=false">取消</el-button><el-button type="primary" @click="confirmImplement">确认落实</el-button></template></el-dialog>
  </div>
</template>
<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import StatCard from '@/components/common/StatCard.vue'
import { CROPS } from '@/mock/common/dict'
import { useUserStore } from '@/stores/user'
import { fetchPlanPlots, implementPlanPlots } from '@/api/gpm'
const userStore = useUserStore(); const crops = CROPS.slice(0, 4); const plots = ref([]); const selected = ref([]); const current = ref(null); const tableRef = ref(null); const dialogVisible = ref(false); const crop = ref('wheat'); const filters = reactive({ crop: '', status: '', keyword: '' })
const filteredPlots = computed(() => plots.value.filter(item => (!filters.crop || item.crop === filters.crop) && (!filters.status || item.status === filters.status) && (!filters.keyword || `${item.id}${item.name}${item.subjectName}`.includes(filters.keyword))))
const implementedCount = computed(() => plots.value.filter(item => item.status === 'implemented').length); const pendingCount = computed(() => plots.value.filter(item => item.status !== 'implemented').length); const implementedArea = computed(() => plots.value.filter(item => item.status === 'implemented').reduce((sum, item) => sum + item.area, 0)); const selectedArea = computed(() => selected.value.reduce((sum, item) => sum + item.area, 0)); const pendingSelected = computed(() => selected.value.filter(item => item.status !== 'implemented')); const implementedSelected = computed(() => selected.value.filter(item => item.status === 'implemented'))
const load = async () => { plots.value = await fetchPlanPlots(userStore.role) }; const showDetail = (row) => { current.value = row }; const implement = () => { crop.value = pendingSelected.value[0]?.crop || 'wheat'; dialogVisible.value = true }; const selectByCrop = () => { const target = filters.crop || 'wheat'; selected.value = filteredPlots.value.filter(item => item.crop === target); ElMessage.info(`已圈选${crops.find(item => item.code === target)?.name || ''}地块 ${selected.value.length} 块`) }; const validateArea = () => { const invalid = plots.value.filter(item => Number(item.area) <= 0); ElMessage[invalid.length ? 'warning' : 'success'](invalid.length ? `发现 ${invalid.length} 块地块面积异常` : '面积校验通过') }; const cancelImplement = async () => { if (!implementedSelected.value.length) return; try { await ElMessageBox.confirm(`确认取消 ${implementedSelected.value.length} 块地块的落实标注？取消后将回到待落实状态。`, '反向标注确认', { type: 'warning' }) } catch { return } const result = await implementPlanPlots({ plotIds: implementedSelected.value.map(item => item.id), role: userStore.role, status: 'cancelled', reason: '人工反向标注' }); if (!result.success) return ElMessage.error(result.message); ElMessage.success(`已取消 ${result.count} 块地块的落实`); selected.value = []; await load() }
const confirmImplement = async () => { const result = await implementPlanPlots({ plotIds: pendingSelected.value.map(item => item.id), crop: crop.value, role: userStore.role }); if (!result.success) return ElMessage.error(result.message); ElMessage.success(`已落实 ${result.count} 块地块`); dialogVisible.value = false; selected.value = []; await load() }
onMounted(load)
</script>
<style lang="scss" scoped>
.implement-page{gap:12px;overflow:auto}.page-head{display:flex;justify-content:space-between;align-items:flex-start}.eyebrow{color:var(--ah-primary);font-size:11px;letter-spacing:1.2px;font-weight:700}h2{margin:4px 0;font-size:22px}.page-head p{color:var(--ah-text-secondary);font-size:13px}.stat-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.content-grid{display:grid;grid-template-columns:minmax(0,1.4fr) minmax(300px,.6fr);gap:12px;min-height:0}.list-panel,.map-panel{min-height:520px}.filters :deep(.el-form-item){margin-bottom:12px}.plot-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;padding:14px;background:#eef5fb;border-radius:8px;min-height:320px}.plot-cell{border:1px solid #f0b94c;background:#fff8e6;border-radius:8px;min-height:72px;cursor:pointer;color:#8a5d00;transition:.2s}.plot-cell:hover,.plot-cell.selected{box-shadow:0 0 0 3px #8fc5f6;transform:translateY(-2px)}.plot-cell.implemented{background:#e9f8ef;border-color:#7bc995;color:#176b3b}.plot-cell span,.plot-cell small{display:block}.plot-cell span{font-weight:700}.plot-cell small{margin-top:6px}.legend{display:flex;gap:16px;margin:14px 0;color:var(--ah-text-secondary);font-size:12px}.legend i{display:inline-block;width:10px;height:10px;border-radius:3px;margin-right:5px;background:#fff0c2;border:1px solid #f0b94c}.legend i.implemented{background:#c9efd5;border-color:#7bc995}.legend i.selected{background:#8fc5f6;border-color:#409eff}.detail-card{padding:14px;background:#f6f8fb;border-radius:8px}.detail-card p{font-size:13px;color:var(--ah-text-secondary);margin:8px 0 12px}@media(max-width:1000px){.stat-grid{grid-template-columns:repeat(2,1fr)}.content-grid{grid-template-columns:1fr}.page-head{display:block}.plot-grid{grid-template-columns:repeat(3,1fr)}}
</style>
